#!/bin/bash
# Generates the BER test vectors used by org.xipki.codec.test.asn1.Asn1BerVectorsTest
# (OpenSSL 3.x is required).
#
# Usage: copy this script to an empty directory, run it, and copy the directories
# definite/ and indefinite/ to this directory. The keys and times are random, so each run
# produces different (but equivalent) files.
#
# definite/:   definite-length encodings that are valid BER but not DER, generated by
#              "openssl asn1parse -genconf". OpenSSL cannot generate constructed strings with
#              definite length (it converts them to the primitive form).
# indefinite/: indefinite-length encodings generated by the streaming mode of "openssl cms"
#              and "openssl smime" (*.ber), and the DER encodings of the same structures
#              re-encoded by OpenSSL (*.der).
set -e
rm -rf definite indefinite work; mkdir -p definite indefinite work; cd work

# ---------- definite length ----------
gen() { # $1: name, stdin: genconf
  cat > $1.cnf
  openssl asn1parse -genconf $1.cnf -out ../definite/$1.ber -noout
}

gen boolean-true-01 <<'C'
asn1 = IMPLICIT:1U,FORMAT:HEX,OCTETSTRING:01
C
gen boolean-true-5a <<'C'
asn1 = IMPLICIT:1U,FORMAT:HEX,OCTETSTRING:5a
C
# SET with elements not in the DER order
gen set-unsorted <<'C'
asn1 = IMPLICIT:17U,SEQUENCE:s
[s]
a = INTEGER:256
b = OCTETSTRING:x
c = INTEGER:1
d = BOOLEAN:TRUE
C
gen utctime-offset <<'C'
asn1 = UTCTIME:260101000000+0130
C
gen generalizedtime-offset <<'C'
asn1 = IMPLICIT:24U,OCTETSTRING:20260101000000-0100
C
gen generalizedtime-fraction <<'C'
asn1 = GENTIME:20260101000000.50Z
C
gen generalizedtime-comma <<'C'
asn1 = IMPLICIT:24U,OCTETSTRING:20260101000000,5Z
C
# All the above nested, also in tagged objects
gen nested <<'C'
asn1 = SEQUENCE:top
[top]
b1 = IMPLICIT:1U,FORMAT:HEX,OCTETSTRING:01
set = IMPLICIT:17U,SEQUENCE:s
# [0] EXPLICIT SEQUENCE { unsorted SET }
expl = EXPLICIT:0,SEQUENCE:wrap
# [1] IMPLICIT SET with unsorted elements
impl = IMPLICIT:1,SEQUENCE:s
seq = SEQUENCE:inner
[wrap]
set = IMPLICIT:17U,SEQUENCE:s
[s]
a = INTEGER:256
b = INTEGER:1
[inner]
b2 = IMPLICIT:1U,FORMAT:HEX,OCTETSTRING:7f
t = UTCTIME:260101000000+0100
C

# ---------- indefinite length ----------
openssl genpkey -algorithm EC -pkeyopt ec_paramgen_curve:P-256 -out ec.key 2>/dev/null
openssl req -new -x509 -key ec.key -subj "/CN=BER Signer" -days 3650 -out ec.pem
openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -out rsa.key 2>/dev/null
openssl req -new -x509 -key rsa.key -subj "/CN=BER Recipient" -days 3650 -out rsa.pem
# content larger than 1 KB: OpenSSL streams it in several OCTET STRING pieces
printf 'hello BER\n' > small.txt
for i in $(seq 1 300); do printf 'line %04d of the streamed content\n' $i; done > large.txt

I=../indefinite
stream() { # $1: name, rest: openssl command
  local name=$1; shift
  "$@" -outform DER -binary -stream -out $I/$name.ber
}
stream cms-data-small     openssl cms -data_create -in small.txt
stream cms-data-large     openssl cms -data_create -in large.txt
stream cms-signed         openssl cms -sign -in small.txt -signer ec.pem -inkey ec.key -nodetach
stream cms-signed-large   openssl cms -sign -in large.txt -signer ec.pem -inkey ec.key -nodetach
stream cms-digested       openssl cms -digest_create -in small.txt
stream cms-enveloped      openssl cms -encrypt -in small.txt -aes-128-cbc -recip rsa.pem
stream cms-enveloped-large openssl cms -encrypt -in large.txt -aes-128-cbc -recip rsa.pem
stream cms-enveloped-pwri openssl cms -encrypt -in small.txt -aes-128-cbc -pwri_password secret
stream cms-authenveloped  openssl cms -encrypt -in small.txt -aes-256-gcm -recip rsa.pem
stream cms-encrypted      openssl cms -EncryptedData_encrypt -in small.txt -aes-128-cbc \
  -secretkey 000102030405060708090a0b0c0d0e0f
openssl smime -sign -in small.txt -signer ec.pem -inkey ec.key -nodetach -outform DER -binary \
  -stream -out $I/pkcs7-signed.ber
openssl smime -encrypt -in small.txt -aes128 -outform DER -binary -stream -out $I/pkcs7-enveloped.ber \
  rsa.pem

# DER encodings re-encoded by OpenSSL
for f in $I/cms-*.ber; do
  openssl cms -cmsout -inform DER -in $f -outform DER -out ${f%.ber}.der
done
for f in $I/pkcs7-*.ber; do
  openssl pkcs7 -inform DER -in $f -outform DER -out ${f%.ber}.der
done
cp small.txt large.txt $I/
cd ..; rm -rf work
